-- =====================================================================
--  Gaming Hub — database schema and demo seed data
--  Generated by database/build_sql.php — edit seed_data.php, not this file.
--
--  Import with phpMyAdmin (Import tab) or from the command line:
--      mysql -u root -p < database/gaming_hub.sql
--
--  WARNING: re-importing DROPS and recreates every Gaming Hub table.
-- =====================================================================

CREATE DATABASE IF NOT EXISTS gaming_hub
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gaming_hub;

SET FOREIGN_KEY_CHECKS = 0;
DROP VIEW  IF EXISTS v_game_ratings;
DROP TABLE IF EXISTS review_reports, review_votes, reviews, wishlists,
                     user_preferences, user_genres, user_platforms,
                     game_genres, game_platforms, game_attributes,
                     games, genres, platforms, users;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
--  Users and accounts
-- ---------------------------------------------------------------------
CREATE TABLE users (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  username      VARCHAR(30)  NOT NULL,
  email         VARCHAR(190) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role          ENUM('user','admin') NOT NULL DEFAULT 'user',
  bio           VARCHAR(280) NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_username (username),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
--  Lookup tables
-- ---------------------------------------------------------------------
CREATE TABLE genres (
  id   SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name VARCHAR(40) NOT NULL,
  slug VARCHAR(40) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_genres_name (name),
  UNIQUE KEY uq_genres_slug (slug)
) ENGINE=InnoDB;

CREATE TABLE platforms (
  id   SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name VARCHAR(40) NOT NULL,
  slug VARCHAR(40) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_platforms_name (name),
  UNIQUE KEY uq_platforms_slug (slug)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
--  Games and their Game DNA
-- ---------------------------------------------------------------------
CREATE TABLE games (
  id                INT UNSIGNED NOT NULL AUTO_INCREMENT,
  title             VARCHAR(120) NOT NULL,
  slug              VARCHAR(140) NOT NULL,
  developer         VARCHAR(120) NOT NULL,
  release_year      SMALLINT UNSIGNED NOT NULL,
  description       TEXT NOT NULL,
  pros              TEXT NULL,          -- one point per line
  cons              TEXT NULL,          -- one point per line
  cover_image       VARCHAR(255) NULL,  -- file name in uploads/covers, NULL = generated artwork
  has_single_player TINYINT(1) NOT NULL DEFAULT 1,
  has_coop          TINYINT(1) NOT NULL DEFAULT 0,
  has_multiplayer   TINYINT(1) NOT NULL DEFAULT 0,
  is_featured       TINYINT(1) NOT NULL DEFAULT 0,
  created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_games_slug (slug),
  KEY idx_games_title (title),
  KEY idx_games_year (release_year),
  KEY idx_games_featured (is_featured)
) ENGINE=InnoDB;

-- Game DNA: editorial 1-10 estimates, one row per game.
CREATE TABLE game_attributes (
  game_id             INT UNSIGNED NOT NULL,
  story_score         TINYINT UNSIGNED NOT NULL,
  combat_score        TINYINT UNSIGNED NOT NULL,
  exploration_score   TINYINT UNSIGNED NOT NULL,
  difficulty_score    TINYINT UNSIGNED NOT NULL,
  replayability_score TINYINT UNSIGNED NOT NULL,
  session_length      ENUM('short','medium','long') NOT NULL,
  completion_hours    SMALLINT UNSIGNED NULL,  -- NULL = open-ended game
  PRIMARY KEY (game_id),
  KEY idx_attr_difficulty (difficulty_score),
  KEY idx_attr_story (story_score),
  CONSTRAINT fk_attr_game FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE,
  CONSTRAINT chk_attr_story   CHECK (story_score BETWEEN 1 AND 10),
  CONSTRAINT chk_attr_combat  CHECK (combat_score BETWEEN 1 AND 10),
  CONSTRAINT chk_attr_explore CHECK (exploration_score BETWEEN 1 AND 10),
  CONSTRAINT chk_attr_diff    CHECK (difficulty_score BETWEEN 1 AND 10),
  CONSTRAINT chk_attr_replay  CHECK (replayability_score BETWEEN 1 AND 10)
) ENGINE=InnoDB;

CREATE TABLE game_genres (
  game_id  INT UNSIGNED NOT NULL,
  genre_id SMALLINT UNSIGNED NOT NULL,
  position TINYINT UNSIGNED NOT NULL DEFAULT 0,  -- 0 = primary genre
  PRIMARY KEY (game_id, genre_id),
  KEY idx_gg_genre (genre_id),
  CONSTRAINT fk_gg_game  FOREIGN KEY (game_id)  REFERENCES games(id)  ON DELETE CASCADE,
  CONSTRAINT fk_gg_genre FOREIGN KEY (genre_id) REFERENCES genres(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE game_platforms (
  game_id     INT UNSIGNED NOT NULL,
  platform_id SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (game_id, platform_id),
  KEY idx_gp_platform (platform_id),
  CONSTRAINT fk_gp_game     FOREIGN KEY (game_id)     REFERENCES games(id)     ON DELETE CASCADE,
  CONSTRAINT fk_gp_platform FOREIGN KEY (platform_id) REFERENCES platforms(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
--  Community: reviews, helpful votes, reports
-- ---------------------------------------------------------------------
CREATE TABLE reviews (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  game_id    INT UNSIGNED NOT NULL,
  user_id    INT UNSIGNED NOT NULL,
  rating     TINYINT UNSIGNED NOT NULL,
  body       TEXT NOT NULL,
  is_hidden  TINYINT(1) NOT NULL DEFAULT 0,  -- hidden by a moderator
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reviews_user_game (user_id, game_id),  -- one review per user per game
  KEY idx_reviews_game (game_id, is_hidden),
  CONSTRAINT fk_reviews_game FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE,
  CONSTRAINT fk_reviews_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT chk_reviews_rating CHECK (rating BETWEEN 1 AND 5)
) ENGINE=InnoDB;

CREATE TABLE review_votes (
  review_id  INT UNSIGNED NOT NULL,
  user_id    INT UNSIGNED NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (review_id, user_id),  -- one helpful vote per user per review
  KEY idx_votes_user (user_id),
  CONSTRAINT fk_votes_review FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE,
  CONSTRAINT fk_votes_user   FOREIGN KEY (user_id)   REFERENCES users(id)   ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE review_reports (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  review_id   INT UNSIGNED NOT NULL,
  reporter_id INT UNSIGNED NOT NULL,
  reason      ENUM('spam','offensive','spoilers','off_topic','other') NOT NULL,
  details     VARCHAR(300) NULL,
  status      ENUM('open','resolved','dismissed') NOT NULL DEFAULT 'open',
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reports_review_user (review_id, reporter_id),
  KEY idx_reports_status (status),
  CONSTRAINT fk_reports_review FOREIGN KEY (review_id)   REFERENCES reviews(id) ON DELETE CASCADE,
  CONSTRAINT fk_reports_user   FOREIGN KEY (reporter_id) REFERENCES users(id)   ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
--  Personal data: wishlist and preferences
-- ---------------------------------------------------------------------
CREATE TABLE wishlists (
  user_id    INT UNSIGNED NOT NULL,
  game_id    INT UNSIGNED NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, game_id),  -- prevents duplicate wishlist entries
  KEY idx_wishlists_game (game_id),
  CONSTRAINT fk_wish_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_wish_game FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Answers from the "What Should I Play?" quiz (NULL = "Any").
CREATE TABLE user_preferences (
  user_id     INT UNSIGNED NOT NULL,
  genre_id    SMALLINT UNSIGNED NULL,
  platform_id SMALLINT UNSIGNED NULL,
  mood        ENUM('adventure','story','challenge','relax','social','quick') NULL,
  play_style  ENUM('solo','coop','multiplayer') NULL,
  difficulty  ENUM('relaxed','balanced','challenging') NULL,
  session     ENUM('short','medium','long') NULL,
  focus       ENUM('story','combat','exploration') NULL,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id),
  CONSTRAINT fk_prefs_user     FOREIGN KEY (user_id)     REFERENCES users(id)     ON DELETE CASCADE,
  CONSTRAINT fk_prefs_genre    FOREIGN KEY (genre_id)    REFERENCES genres(id)    ON DELETE SET NULL,
  CONSTRAINT fk_prefs_platform FOREIGN KEY (platform_id) REFERENCES platforms(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Favourite genres / platforms chosen on the profile page.
CREATE TABLE user_genres (
  user_id  INT UNSIGNED NOT NULL,
  genre_id SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (user_id, genre_id),
  CONSTRAINT fk_ug_user  FOREIGN KEY (user_id)  REFERENCES users(id)  ON DELETE CASCADE,
  CONSTRAINT fk_ug_genre FOREIGN KEY (genre_id) REFERENCES genres(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE user_platforms (
  user_id     INT UNSIGNED NOT NULL,
  platform_id SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (user_id, platform_id),
  CONSTRAINT fk_up_user     FOREIGN KEY (user_id)     REFERENCES users(id)     ON DELETE CASCADE,
  CONSTRAINT fk_up_platform FOREIGN KEY (platform_id) REFERENCES platforms(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
--  Community rating per game, calculated from visible reviews only
-- ---------------------------------------------------------------------
CREATE VIEW v_game_ratings AS
  SELECT game_id,
         AVG(rating) AS avg_rating,
         COUNT(*)    AS review_count
  FROM reviews
  WHERE is_hidden = 0
  GROUP BY game_id;

