INSERT INTO games (id, title, slug, developer, release_year, description, pros, cons, has_single_player, has_coop, has_multiplayer, is_featured) VALUES
  (1, 'Hollow Knight', 'hollow-knight', 'Team Cherry', 2017, 'A hand-drawn action platformer set in Hallownest, a ruined underground kingdom of insects. You explore a huge interconnected map, unlock new movement abilities and take on demanding boss fights.', 'Huge, interconnected world full of secrets
