INSERT INTO reviews (id, game_id, user_id, rating, body, created_at) VALUES
  (1, 1, 3, 5, 'The map keeps opening up long after you think you have seen it all. Every new ability made me want to revisit old areas.', DATE_SUB(NOW(), INTERVAL 40 DAY)),
  (2, 1, 12, 3, 'Beautiful, but I got lost a lot early on and some bosses took me dozens of tries. Worth it if you are patient.', DATE_SUB(NOW(), INTERVAL 12 DAY)),
  (3, 1, 7, 5, 'Combat is simple on paper but the bosses demand real precision. Some of the best fights in the genre.', DATE_SUB(NOW(), INTERVAL 75 DAY)),
  (4, 2, 9, 5, 'My comfort game. I play a few in-game days before bed and it never stresses me out.', DATE_SUB(NOW(), INTERVAL 30 DAY)),
  (5, 2, 11, 5, 'Co-op farm with my sister has been the best part of our week for months.', DATE_SUB(NOW(), INTERVAL 64 DAY)),
  (6, 2, 5, 4, 'Great for short sessions. The first season felt slow until I figured out sprinklers.', DATE_SUB(NOW(), INTERVAL 8 DAY)),
  (7, 2, 2, 5, 'I came for the farming and stayed for the townspeople. Their stories are surprisingly sweet.', DATE_SUB(NOW(), INTERVAL 21 DAY)),
  (8, 3, 7, 5, 'Every death is your own fault and respawns are instant, so it never feels unfair. The final chapter is incredible.', DATE_SUB(NOW(), INTERVAL 50 DAY)),
  (9, 3, 4, 5, 'I did not expect a platformer to say something this honest about anxiety.', DATE_SUB(NOW(), INTERVAL 33 DAY)),
  (10, 3, 12, 4, 'Turned on assist mode for a couple of screens and do not regret it. Tough but kind.', DATE_SUB(NOW(), INTERVAL 5 DAY)),
  (11, 4, 5, 5, 'A run takes about half an hour, which is perfect for weeknights. The story moving forward after each death is genius.', DATE_SUB(NOW(), INTERVAL 18 DAY)),
  (12, 4, 4, 5, 'Every character has so much dialogue that I kept dying on purpose to hear more.', DATE_SUB(NOW(), INTERVAL 60 DAY)),
  (13, 4, 7, 5, 'Weapon aspects and boons combine in so many ways. Still finding new builds after 80 hours.', DATE_SUB(NOW(), INTERVAL 90 DAY)),
  (14, 4, 12, 4, 'Hard at first, but you get stronger between runs so it never felt hopeless.', DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (15, 5, 4, 5, 'Side quests here are better than the main story in most games. The Bloody Baron questline stayed with me.', DATE_SUB(NOW(), INTERVAL 100 DAY)),
  (16, 5, 10, 4, 'Huge world and great quests, but the combat never fully clicked for me.', DATE_SUB(NOW(), INTERVAL 45 DAY)),
  (17, 5, 2, 5, 'Took me 90 hours with the expansions and I would happily do it again.', DATE_SUB(NOW(), INTERVAL 14 DAY)),
  (18, 6, 3, 5, 'Turning a corner and finding an entire hidden area never stopped being exciting.', DATE_SUB(NOW(), INTERVAL 25 DAY)),
  (19, 6, 10, 5, 'If a boss is too hard you can go somewhere else and come back stronger. That freedom changes everything.', DATE_SUB(NOW(), INTERVAL 70 DAY)),
  (20, 6, 12, 3, 'Amazing world but I bounced off the difficulty a few times. Co-op summons saved me.', DATE_SUB(NOW(), INTERVAL 9 DAY)),
  (21, 6, 7, 5, 'Brutal and fair. Some of the best boss design in any game.', DATE_SUB(NOW(), INTERVAL 55 DAY)),
  (22, 7, 6, 5, 'Puzzles that make you feel smart without ever explaining the solution. The writing is hilarious.', DATE_SUB(NOW(), INTERVAL 120 DAY)),
  (23, 7, 8, 5, 'The co-op campaign is the reason to play. Lots of laughing and accidental portal deaths.', DATE_SUB(NOW(), INTERVAL 80 DAY)),
  (24, 8, 8, 5, 'Our friend server has been running for two years. Nothing else gives this much freedom.', DATE_SUB(NOW(), INTERVAL 35 DAY)),
  (25, 8, 9, 4, 'Creative mode is my relaxation. Survival at night is a bit too tense for me.', DATE_SUB(NOW(), INTERVAL 27 DAY)),
  (26, 8, 12, 4, 'Had no idea what to do at first. Once a friend showed me the basics I was hooked.', DATE_SUB(NOW(), INTERVAL 2 DAY)),
  (27, 9, 8, 5, 'Every chapter feels like a new game. Best co-op experience I have had.', DATE_SUB(NOW(), INTERVAL 48 DAY)),
  (28, 9, 11, 4, 'Gameplay variety is amazing. The story was a little cheesy but we still loved it.', DATE_SUB(NOW(), INTERVAL 15 DAY)),
  (29, 10, 4, 5, 'Arthur Morgan is one of the best characters in gaming. The ending wrecked me.', DATE_SUB(NOW(), INTERVAL 110 DAY)),
  (30, 10, 5, 3, 'Gorgeous, but everything is slow. Hard to make progress in a one-hour session.', DATE_SUB(NOW(), INTERVAL 20 DAY)),
  (31, 10, 10, 5, 'Spent hours just hunting and riding around. The world feels alive.', DATE_SUB(NOW(), INTERVAL 66 DAY)),
  (32, 11, 4, 5, 'The best writing I have ever seen in a game. Failing checks is often more interesting than passing them.', DATE_SUB(NOW(), INTERVAL 52 DAY)),
  (33, 11, 2, 5, 'No combat at all and I never missed it. Every conversation is a skill check and a joke at the same time.', DATE_SUB(NOW(), INTERVAL 11 DAY)),
  (34, 11, 7, 3, 'Impressive, but it is basically a novel. Not for me — I need some action.', DATE_SUB(NOW(), INTERVAL 38 DAY)),
  (35, 12, 5, 4, 'Five-minute matches are perfect when I only have a little time.', DATE_SUB(NOW(), INTERVAL 16 DAY)),
  (36, 12, 8, 5, 'Split-screen with friends is endless fun even when none of us can hit aerials.', DATE_SUB(NOW(), INTERVAL 44 DAY)),
  (37, 12, 12, 3, 'Fun, but online players are much better than me. Big learning curve.', DATE_SUB(NOW(), INTERVAL 6 DAY)),
  (38, 13, 8, 5, 'With the right group of friends on voice chat this is pure chaos. With strangers, not so much.', DATE_SUB(NOW(), INTERVAL 90 DAY)),
  (39, 13, 11, 3, 'Great fun at parties, but you really need a group.', DATE_SUB(NOW(), INTERVAL 58 DAY)),
  (40, 14, 11, 5, 'Every run makes me think about my deck differently. Seeing enemy intentions makes it feel fair.', DATE_SUB(NOW(), INTERVAL 37 DAY)),
  (41, 14, 5, 5, 'I can save mid-run and come back later. Perfect commute game on my phone.', DATE_SUB(NOW(), INTERVAL 10 DAY)),
  (42, 14, 10, 4, 'Very deep, though the later ascension levels get punishing.', DATE_SUB(NOW(), INTERVAL 82 DAY)),
  (43, 15, 10, 5, 'My choices genuinely changed what happened. 120 hours and I want to start again with a different class.', DATE_SUB(NOW(), INTERVAL 30 DAY)),
  (44, 15, 2, 5, 'Played the whole campaign in co-op with a friend. Companions are wonderful.', DATE_SUB(NOW(), INTERVAL 19 DAY)),
  (45, 15, 5, 3, 'Incredible game, but it needs long sessions. Turn-based fights take a while.', DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (46, 15, 4, 5, 'Dialogue and reactivity on another level. Felt like a real tabletop campaign.', DATE_SUB(NOW(), INTERVAL 50 DAY)),
  (47, 16, 6, 5, 'See a mountain, climb the mountain. Exploration has never felt this free.', DATE_SUB(NOW(), INTERVAL 140 DAY)),
  (48, 16, 3, 4, 'Loved the freedom. Weapon durability annoyed me until I learned to stop hoarding.', DATE_SUB(NOW(), INTERVAL 63 DAY)),
  (49, 17, 9, 5, 'Pure joy. Every kingdom has so many surprises, and it never gets stressful.', DATE_SUB(NOW(), INTERVAL 29 DAY)),
  (50, 17, 12, 4, 'Easy to get into. Played it with my younger brother controlling Cappy.', DATE_SUB(NOW(), INTERVAL 13 DAY)),
  (51, 18, 9, 5, 'Ten minutes every morning with my coffee. Exactly what I need.', DATE_SUB(NOW(), INTERVAL 85 DAY)),
  (52, 18, 11, 4, 'Lovely, but waiting a real day for buildings tests my patience.', DATE_SUB(NOW(), INTERVAL 41 DAY)),
  (53, 19, 7, 5, 'When the deflect rhythm finally clicks it feels like a dance. Hardest game I have beaten and the most rewarding.', DATE_SUB(NOW(), INTERVAL 72 DAY)),
  (54, 19, 12, 2, 'Stuck on the second big boss for a week. No difficulty options made me give up.', DATE_SUB(NOW(), INTERVAL 4 DAY)),
  (55, 20, 8, 4, 'Great with a regular team. Solo queue can be frustrating.', DATE_SUB(NOW(), INTERVAL 23 DAY)),
  (56, 20, 7, 3, 'Heroes are fun but balance changes happen so often that it is hard to keep up.', DATE_SUB(NOW(), INTERVAL 49 DAY)),
  (57, 21, 7, 4, 'Precise and tactical. Very rewarding once you learn the maps, very harsh before that.', DATE_SUB(NOW(), INTERVAL 31 DAY)),
  (58, 21, 12, 3, 'Matches are long and mistakes are punished hard. Fun when it works.', DATE_SUB(NOW(), INTERVAL 1 DAY)),
  (59, 22, 8, 4, 'Squads with friends on a Friday night is a tradition. Zero build mode helps a lot.', DATE_SUB(NOW(), INTERVAL 17 DAY)),
  (60, 22, 5, 3, 'Fun in short bursts but the constant updates mean I never know what is going on.', DATE_SUB(NOW(), INTERVAL 26 DAY)),
  (61, 23, 6, 5, 'Go in blind. The moment everything comes together is something I will never forget.', DATE_SUB(NOW(), INTERVAL 95 DAY)),
  (62, 23, 3, 5, 'No upgrades, just knowledge. One of the most original games ever made.', DATE_SUB(NOW(), INTERVAL 54 DAY)),
  (63, 23, 12, 4, 'I got lost a few times but taking notes helped. Amazing once it clicked.', DATE_SUB(NOW(), INTERVAL 11 DAY)),
  (64, 24, 6, 5, 'The ocean is beautiful and terrifying. Building my first underwater base was magical.', DATE_SUB(NOW(), INTERVAL 61 DAY)),
  (65, 24, 9, 3, 'Lovely in shallow water but the deep parts were too scary for me.', DATE_SUB(NOW(), INTERVAL 39 DAY)),
  (66, 25, 8, 5, 'Hundreds of hours with friends. There is always another boss or biome to tackle.', DATE_SUB(NOW(), INTERVAL 77 DAY)),
  (67, 25, 3, 4, 'So much content. I keep a wiki open the whole time though.', DATE_SUB(NOW(), INTERVAL 34 DAY)),
  (68, 26, 7, 5, 'Parrying a chainsaw with a knife never gets old. Excellent remake.', DATE_SUB(NOW(), INTERVAL 28 DAY)),
  (69, 26, 4, 4, 'Better story than I remembered from the original. Tense without being too scary.', DATE_SUB(NOW(), INTERVAL 46 DAY)),
  (70, 27, 6, 5, 'Three hours of pure atmosphere. That ending...', DATE_SUB(NOW(), INTERVAL 150 DAY)),
  (71, 27, 5, 4, 'Short enough to finish over two evenings. Some puzzles are clever.', DATE_SUB(NOW(), INTERVAL 22 DAY)),
  (72, 28, 9, 5, 'Meeting a stranger and travelling together without words was moving.', DATE_SUB(NOW(), INTERVAL 130 DAY)),
  (73, 28, 4, 4, 'Short, but every minute is beautiful.', DATE_SUB(NOW(), INTERVAL 87 DAY)),
  (74, 29, 11, 5, 'I sat down at 8pm and suddenly it was 2am. Dangerous game.', DATE_SUB(NOW(), INTERVAL 57 DAY)),
  (75, 29, 10, 4, 'Endless replay value, though late-game turns get slow on big maps.', DATE_SUB(NOW(), INTERVAL 105 DAY)),
  (76, 30, 11, 4, 'Losing a veteran soldier hurts. Tense decisions every turn.', DATE_SUB(NOW(), INTERVAL 68 DAY)),
  (77, 30, 7, 3, 'Missing a 95% shot is pain. Great design but frustrating sometimes.', DATE_SUB(NOW(), INTERVAL 99 DAY)),
  (78, 31, 8, 5, 'The default party game at every get-together.', DATE_SUB(NOW(), INTERVAL 42 DAY)),
  (79, 31, 9, 4, 'Smart steering means anyone can join in. Lots of fun.', DATE_SUB(NOW(), INTERVAL 36 DAY)),
  (80, 32, 5, 4, 'Jump in, do a couple of races, done. Mexico looks stunning.', DATE_SUB(NOW(), INTERVAL 24 DAY)),
  (81, 32, 12, 4, 'Assist options made it easy for me as a non-racing fan.', DATE_SUB(NOW(), INTERVAL 8 DAY)),
  (82, 33, 7, 5, 'Modern controls got my friends into fighting games. Training mode is excellent.', DATE_SUB(NOW(), INTERVAL 20 DAY)),
  (83, 33, 12, 3, 'Ranked is scary. World Tour was fun to learn the basics though.', DATE_SUB(NOW(), INTERVAL 14 DAY)),
  (84, 34, 8, 5, 'Eight-player chaos with friends is unbeatable.', DATE_SUB(NOW(), INTERVAL 88 DAY)),
  (85, 34, 7, 4, 'Deep competitive game hiding under a party game.', DATE_SUB(NOW(), INTERVAL 112 DAY)),
  (86, 35, 7, 5, 'Every boss is a pattern puzzle. Looks like a playable cartoon.', DATE_SUB(NOW(), INTERVAL 73 DAY)),
  (87, 35, 5, 3, 'Gorgeous but I can only handle a few attempts before I need a break.', DATE_SUB(NOW(), INTERVAL 32 DAY)),
  (88, 36, 3, 5, 'Combat feels amazing. Every run unlocks something new.', DATE_SUB(NOW(), INTERVAL 47 DAY)),
  (89, 36, 7, 4, 'Boss cells difficulty gets wild. Great action.', DATE_SUB(NOW(), INTERVAL 59 DAY)),
  (90, 37, 9, 5, 'The calmest game I own, and the story told through objects made me tear up.', DATE_SUB(NOW(), INTERVAL 44 DAY)),
  (91, 37, 6, 4, 'Short and sweet. Lovely little puzzles.', DATE_SUB(NOW(), INTERVAL 66 DAY)),
  (92, 38, 9, 5, 'A cosy game about saying goodbye. I cried several times.', DATE_SUB(NOW(), INTERVAL 53 DAY)),
  (93, 38, 4, 4, 'Beautiful story. Some fetch tasks dragged a bit.', DATE_SUB(NOW(), INTERVAL 71 DAY)),
  (94, 39, 8, 5, 'Screaming with friends in voice chat. Best co-op horror around.', DATE_SUB(NOW(), INTERVAL 19 DAY)),
  (95, 39, 12, 3, 'Played alone and it was mostly confusing. Needs friends.', DATE_SUB(NOW(), INTERVAL 3 DAY)),
  (96, 40, 4, 5, 'Bold, strange and unforgettable. The musical chapter is a highlight.', DATE_SUB(NOW(), INTERVAL 26 DAY)),
  (97, 40, 3, 3, 'Loved the atmosphere, but long stretches with little gameplay.', DATE_SUB(NOW(), INTERVAL 48 DAY)),
  (98, 41, 4, 5, 'A surprisingly tender father-son story with heavy, satisfying combat.', DATE_SUB(NOW(), INTERVAL 102 DAY)),
  (99, 41, 10, 4, 'Great combat and realms to explore. Some puzzles slowed me down.', DATE_SUB(NOW(), INTERVAL 81 DAY)),
  (100, 42, 12, 5, 'Swinging around the city never gets old. Easy to enjoy even as a beginner.', DATE_SUB(NOW(), INTERVAL 15 DAY)),
  (101, 42, 5, 4, 'Easy to jump in for a mission or two. Side content repeats itself.', DATE_SUB(NOW(), INTERVAL 41 DAY)),
  (102, 43, 2, 5, 'Over 100 hours and I was sad when it ended. The style and music are unmatched.', DATE_SUB(NOW(), INTERVAL 27 DAY)),
  (103, 43, 5, 3, 'Loved it but the opening hours are very slow and it is massive.', DATE_SUB(NOW(), INTERVAL 62 DAY)),
  (104, 44, 10, 5, 'Four friends, one huge monster, perfect evening. I have 400 hours in this.', DATE_SUB(NOW(), INTERVAL 93 DAY)),
  (105, 44, 12, 3, 'Tutorials did not explain enough. Much better once a friend helped.', DATE_SUB(NOW(), INTERVAL 7 DAY)),
  (106, 45, 8, 5, 'Rock and stone! The best co-op shooter for a group of friends.', DATE_SUB(NOW(), INTERVAL 22 DAY)),
  (107, 45, 3, 4, 'Solo with Bosco is fine, but this shines with a full team.', DATE_SUB(NOW(), INTERVAL 50 DAY)),
  (108, 46, 9, 5, 'I get into a trance with the music. Perfect for unwinding.', DATE_SUB(NOW(), INTERVAL 16 DAY)),
  (109, 46, 5, 4, 'Fifteen minutes of zone mode and my day feels better.', DATE_SUB(NOW(), INTERVAL 9 DAY)),
  (110, 47, 4, 5, 'Funny, surprising and kind. Remembering my choices across saves blew my mind.', DATE_SUB(NOW(), INTERVAL 115 DAY)),
  (111, 47, 6, 4, 'Short but packed with personality.', DATE_SUB(NOW(), INTERVAL 98 DAY)),
  (112, 48, 3, 5, 'Movement flows beautifully. One of the prettiest games I have played.', DATE_SUB(NOW(), INTERVAL 69 DAY)),
  (113, 48, 9, 3, 'Gorgeous, but the escape sequences were too stressful for me.', DATE_SUB(NOW(), INTERVAL 85 DAY)),
  (114, 49, 6, 5, 'Every level is a giant puzzle box. I replay Dartmoor constantly.', DATE_SUB(NOW(), INTERVAL 43 DAY)),
  (115, 49, 10, 4, 'Endless challenges to complete. Story is just background.', DATE_SUB(NOW(), INTERVAL 74 DAY)),
  (116, 50, 10, 4, 'Exploration is fantastic for a free game. Ignore the gacha and it is great.', DATE_SUB(NOW(), INTERVAL 35 DAY)),
  (117, 50, 5, 3, 'Daily resin limit means I just log in for 20 minutes. Works for me sometimes.', DATE_SUB(NOW(), INTERVAL 12 DAY)),
  (118, 50, 13, 1, 'FREE PRIMOGEMS!!! visit my channel for codes, best website, click now', DATE_SUB(NOW(), INTERVAL 2 DAY));
